S = "Hakeem Force Academy"
QS = [
(S, "What is the currency of Afghanistan?", ["Afghani", "Rupee", "Dirham", "Rial"], 0, "The official currency of Afghanistan is the Afghani (AFN). It is divided into 100 puls.", "The Afghani replaced the older Afghani in 2002 with new banknotes after the fall of the Taliban government.", [2832]),
(S, "What is the currency of Finland?", ["Krona", "Euro", "Mark", "Krone"], 1, "Finland is a member of the Eurozone and uses the Euro. It replaced the Finnish markka in 2002.", "Finland adopted the Euro in 1999 for accounts and 2002 for cash.", [2835]),
(S, "Which currency has the highest value per unit in the world?", ["Kuwaiti Dinar", "US Dollar", "British Pound", "Euro"], 0, "The Kuwaiti Dinar (KWD) is worth more than any other currency unit, over 3 US dollars each. Its strength comes from Kuwait's oil wealth and tight currency policy.", "The Bahraini Dinar and Omani Rial are the next most valuable currency units.", [3728]),
(S, "Which constitution is currently in force in Pakistan?", ["Constitution of 1973", "Constitution of 1962", "Constitution of 1956", "Government of India Act 1935"], 0, "Pakistan is governed by the Constitution of 1973, passed by the National Assembly under Zulfikar Ali Bhutto. It was enforced on 14 August 1973.", "The 1973 Constitution has been amended many times, including the 18th Amendment in 2010.", [470, 3688]),
(S, "Who is the current President of Pakistan (as of October 2026)?", ["Asif Ali Zardari", "Arif Alvi", "Mamnoon Hussain", "Shehbaz Sharif"], 0, "Asif Ali Zardari was sworn in as the 14th President of Pakistan on 10 March 2024 and still holds the office. The President is elected by an electoral college of Parliament and provincial assemblies.", "Zardari's predecessor was Dr Arif Alvi, who served from 2018 to 2024.", [4208]),
(S, "What does the idiom 'a dark horse' mean?", ["A little-known person who unexpectedly wins or succeeds", "A very angry person", "A person who is always late", "A rich and famous person"], 0, "A dark horse is a person or competitor about whom little is known but who may surprise everyone by winning. The idiom comes from horse racing.", "The phrase became popular in politics after a surprise candidate won the US nomination in 1844.", [2579, 984]),
(S, "In which direction from Karachi is Mohenjo-daro located?", ["North-east", "South-west", "North-west", "South"], 0, "Mohenjo-daro is near Larkana in northern Sindh, which lies north-east of Karachi. It is on the right bank of the Indus river.", "Mohenjo-daro was declared a UNESCO World Heritage Site in 1980.", [2333]),
(S, "On which date was the United Nations officially founded (the Charter came into force)?", ["24 October 1945", "26 June 1945", "10 December 1948", "1 January 1942"], 0, "The UN Charter came into force on 24 October 1945 after enough countries ratified it. This date is celebrated every year as United Nations Day.", "The Charter was signed earlier, on 26 June 1945, in San Francisco.", [2864]),
(S, "Which article of the 1973 Constitution of Pakistan provides the right to free and compulsory education to children aged 5 to 16?", ["Article 25A", "Article 18", "Article 19", "Article 23"], 0, "Article 25A was added by the 18th Amendment in 2010. It obliges the State to give free and compulsory education to children from 5 to 16 years.", "Article 37(b) also directs the State to remove illiteracy and provide free secondary education.", [3633]),
(S, "On which date was Liaquat Ali Khan assassinated?", ["16 October 1951", "14 August 1951", "11 September 1951", "23 March 1951"], 0, "Liaquat Ali Khan, the first Prime Minister of Pakistan, was shot at a public meeting in Rawalpindi on 16 October 1951. The assassin Said Akbar was killed on the spot.", "The place of the assassination, Company Bagh, was later renamed Liaquat Bagh.", [2842]),
(S, "What was the age of the Holy Prophet Muhammad (SAW) at the time of his death?", ["63 years", "60 years", "65 years", "53 years"], 0, "The Prophet (SAW) was born in 570 CE and passed away in 632 CE (11 Hijri), at the age of 63 according to the most accepted view. He passed away in Madina.", "He received the first revelation at the age of 40.", [3300]),
(S, "Which law or principle states that a body immersed in a fluid experiences an upward force equal to the weight of the fluid it displaces?", ["Archimedes' principle", "Pascal's law", "Bernoulli's principle", "Boyle's law"], 0, "This is the statement of Archimedes' principle. The upward force is called buoyant force and explains why ships float.", "Archimedes is said to have discovered the principle while taking a bath in ancient Greece.", [2870]),
(S, "How many degrees are there in a full circle?", ["360", "180", "270", "400"], 0, "A full turn around a circle is 360 degrees by definition. A half circle is 180 and a quarter circle is 90.", "The 360 degree system comes from the ancient Babylonians, who used a base-60 number system.", [1704]),
(S, "How many minutes are there in 10 degrees according to the degree-minute-second (DMS) system?", ["600", "60", "360", "100"], 0, "One degree equals 60 minutes. So 10 degrees = 10 x 60 = 600 minutes.", "One minute of arc is further divided into 60 seconds.", [1747]),
(S, "In which year was the Babri Mosque in Ayodhya demolished?", ["1992", "1984", "1989", "2002"], 0, "The Babri Mosque was demolished by Hindu extremist mobs on 6 December 1992. The event led to widespread riots in India.", "In 2019 the Indian Supreme Court gave the disputed site for a Hindu temple.", [2177]),
(S, "Which word is a synonym of 'denounce'?", ["Condemn", "Praise", "Support", "Admire"], 0, "To denounce means to publicly criticise or condemn something as wrong. Condemn has the same meaning.", "The opposites (antonyms) of denounce include praise and applaud.", [2663, 3172]),
(S, "Evaporation of water does NOT depend upon which of the following?", ["Depth of water", "Temperature", "Surface area", "Wind speed"], 0, "Evaporation happens at the surface, so it depends on temperature, surface area, humidity and wind. The depth of the water does not change the rate.", "Evaporation is faster in hot, dry and windy conditions.", [1553]),
(S, "What is the derivative of 2x sin x with respect to x?", ["2 sin x + 2x cos x", "2 cos x", "2x cos x", "2 sin x - 2x cos x"], 0, "Use the product rule: d/dx (u v) = u'v + u v' with u = 2x and v = sin x. This gives 2 sin x + 2x cos x.", "The product rule is also called Leibniz's rule.", [956]),
(S, "What is the derivative of ln x with respect to x?", ["1/x", "x", "ln x", "e to the power x"], 0, "The natural logarithm ln x has derivative 1/x for x greater than zero. This is a standard result of calculus.", "The derivative of e to the power x is e to the power x itself.", [957]),
(S, "Which is considered the largest desert of Pakistan?", ["Thar Desert", "Cholistan Desert", "Kharan Desert", "Thal Desert"], 0, "Most Pakistani textbooks name the Thar Desert in Sindh as the largest desert of Pakistan. It is shared with India.", "Sources differ: some measure only the Pakistani portion, where Cholistan is also large.", [2715, 62]),
(S, "Which is the largest desert in the world by area?", ["Antarctic Desert", "Sahara Desert", "Arabian Desert", "Gobi Desert"], 0, "A desert is an area with very little precipitation, and Antarctica, at about 14 million square km, is the largest. The Sahara is the largest hot desert.", "The Arctic Desert is the second largest and the Sahara is third.", [486]),
]
